-- RC-870 (RP-123): the variant comparison reads otel_trace_summaries by (project, experiment, variant,
-- started_at) inside a time window, behind FF_VARIANT_EXPERIMENTS. Generated by drizzle-kit from
-- synthesis/traces/schema.ts, then written as upstream's 0118 (ratel-cloud): IF NOT EXISTS, so a
-- database migrated by ratel-cloud already has it and this is a no-op there. The index is partial
-- (tagged traces only), so it holds no entry for the rows written before the switch. drizzle's
-- migrate() runs this in a transaction, where a plain CREATE INDEX blocks writes on
-- otel_trace_summaries for one scan. On a large otel_trace_summaries, build it first, outside a
-- transaction (psql autocommit):
--   CREATE INDEX CONCURRENTLY IF NOT EXISTS "otel_trace_summaries_project_variant_started_idx" ON "otel_trace_summaries" USING btree ("project_id","variant_experiment","variant_name","started_at") WHERE "variant_experiment" is not null and "variant_name" is not null;
-- The statement here is then a no-op. If a CONCURRENTLY build fails it leaves an INVALID index:
-- DROP INDEX CONCURRENTLY it and run it again.
CREATE INDEX IF NOT EXISTS "otel_trace_summaries_project_variant_started_idx" ON "otel_trace_summaries" USING btree ("project_id","variant_experiment","variant_name","started_at") WHERE "otel_trace_summaries"."variant_experiment" is not null and "otel_trace_summaries"."variant_name" is not null;
